def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    prev_bids = []
    dangerous_prev = 0.0
    rich_count = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('budget', 0) >= DAILY_SALARY * 2:
                rich_count += 1
            prev = opp.get('previous_trace', {}) or {}
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))
                pressure = float(bid)
                if opp.get('no_water_days', 0) >= 2 or opp.get('hp', 10) <= 3:
                    pressure += 8.0
                if pressure > dangerous_prev:
                    dangerous_prev = pressure

    if budget <= 0:
        return 0.0

    if not alive:
        return float(min(budget, max(1.0, DAILY_SALARY * 0.35)))

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    scarcity = max(0.0, min(1.0, scarcity))

    urgency = 0.0
    if hp <= 2:
        urgency += 1.0
    elif hp <= 4:
        urgency += 0.55
    if no_water_days >= 2:
        urgency += 1.0
    elif no_water_days == 1:
        urgency += 0.35

    if prev_bids:
        highest_prev = max(prev_bids)
        avg_prev = sum(prev_bids) / len(prev_bids)
    else:
        highest_prev = 0.0
        avg_prev = 0.0

    base = DAILY_SALARY * (0.42 + 0.28 * scarcity)
    if rich_count >= 2:
        base += 6.0

    target = base
    if scarcity > 0.6:
        target = max(target, dangerous_prev + 2.5, highest_prev + 1.5)
    elif scarcity > 0.3:
        target = max(target, avg_prev + 2.0)
    else:
        target = max(target, avg_prev * 0.82)

    if urgency >= 1.0:
        target = max(target, DAILY_SALARY * 0.92, dangerous_prev + 4.0)
    elif urgency > 0.0:
        target += 10.0 * urgency

    if day >= 8:
        target += 6.0
    if day == 10:
        target += 10.0

    if budget < DAILY_SALARY * 1.2:
        target = min(target, budget * 0.82 + 4.0)
    elif budget > DAILY_SALARY * 4:
        target += 5.0

    floor_bid = 1.0
    if urgency >= 1.0:
        floor_bid = DAILY_SALARY * 0.75
    elif scarcity > 0.6:
        floor_bid = DAILY_SALARY * 0.55
    elif scarcity < 0.2 and hp > 5 and no_water_days == 0:
        floor_bid = DAILY_SALARY * 0.28

    bid = max(floor_bid, target)
    bid = min(bid, budget)
    if bid < 0:
        bid = 0.0
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']

    # Alive opponents
    alive_opps = []
    for k, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((k, o))

    # If no one else alive, bid low but enough to likely win
    if not alive_opps:
        return float(min(my_status['budget'], DAILY_SALARY * 0.4))

    # Use only yesterday previous_trace for immediate reaction
    prev_bids = []
    prev_max_bid = None
    for _, o in alive_opps:
        pt = o.get('previous_trace', {})
        if pt and pt.get('bid') is not None:
            b = pt.get('bid')
            try:
                b = float(b)
            except Exception:
                continue
            prev_bids.append(b)
            if prev_max_bid is None or b > prev_max_bid:
                prev_max_bid = b

    # Estimate number of winners: bids compete for limited supply.
    # If supply is high, we can bid less; if low, bid more.
    # Normalize supply within [MIN_SUPPLY, MAX_SUPPLY].
    try:
        s_norm = (float(supply) - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
    except Exception:
        s_norm = 0.5
    if s_norm < 0.0:
        s_norm = 0.0
    if s_norm > 1.0:
        s_norm = 1.0

    # Base bid: mid-level to avoid getting priced out by heavy bidders.
    # If supply is low (near 15), increase bid.
    base = DAILY_SALARY * (0.42 + 0.25 * (1.0 - s_norm))

    # If someone previously bid extremely high, we must at least match a fraction.
    # Cindy's behavior suggests some agents will keep spending aggressively.
    if prev_max_bid is not None:
        prev_max_bid = float(prev_max_bid)
        # Threshold relative to salary
        if prev_max_bid >= DAILY_SALARY * 1.2:
            # Compete more when others were willing to overspend
            urgency = 1.0
        elif prev_max_bid >= DAILY_SALARY * 0.8:
            urgency = 0.7
        else:
            urgency = 0.5
    else:
        urgency = 0.55

    # HP/budget pressure
    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status.get('no_water_days', 0))

    # If we're close to dying or have already missed water, bid harder.
    if hp <= 2.0 or no_water_days >= 2:
        pressure = 1.0
    elif hp <= 4.0 or no_water_days >= 1:
        pressure = 0.75
    else:
        pressure = 0.55

    # Target bid combines base with a fraction of previous max bid.
    # Use int() only where indexing would occur (none here), but keep floats.
    target = base * (0.85 + 0.6 * urgency) + (0.12 * (prev_max_bid if prev_max_bid is not None else 0.0))
    target *= (0.75 + 0.5 * pressure)

    # Do not exceed budget; also cap to avoid runaway overspending.
    # Since daily_salary=140, a safe cap around 1.0-1.1 salary is reasonable.
    cap = DAILY_SALARY * 1.05
    bid = min(budget, cap, target)

    # If budget is very low, still try to get water if survival is at risk.
    if budget <= DAILY_SALARY * 0.25:
        if hp <= 3.0 or no_water_days >= 1:
            bid = min(budget, DAILY_SALARY * 0.9)
        else:
            bid = min(budget, DAILY_SALARY * 0.35)

    # Ensure non-negative
    if bid < 0.0:
        bid = 0.0

    return float(bid)
